import json,pathlib,copy
p=pathlib.Path(__file__).parent
g=json.loads((p/'dag.json').read_text())
P='https://www.postgresql.org/docs/18/transaction-iso.html'
T='https://www.postgresql.org/docs/18/tutorial-transactions.html'
M='https://dev.mysql.com/doc/refman/8.4/en/innodb-transaction-isolation-levels.html'
S='https://www.sqlite.org/isolation.html'
V='https://www.postgresql.org/docs/18/mvcc-intro.html'
def ev(url,locator,claim,basis='supplied packet, checked against live relevant section'):
 return {'url':url,'locator':locator,'claim':claim,'basis':basis}
def put(i,answer,evidence):
 n=next(n for n in g['nodes'] if n['id']==i)
 n.update(answer=answer,status='supported',evidence=evidence)
put('transaction','A transaction groups SQL work into one completion unit. BEGIN starts an explicit group; COMMIT retains its work; ROLLBACK discards it. A connection is an application conversation with the database, and separate connections can run separate transactions. PostgreSQL implicitly wraps a standalone statement in a transaction.',[ev(T,'3.4, BEGIN/COMMIT/ROLLBACK and implicit statement transactions','Defines transaction boundaries and completion.'),ev(S,'Isolation Between Database Connections','Separate connections can have separate concurrent transactions.')])
put('atomicity','Atomicity means all updates in a transaction survive together or none do. A transfer must debit and credit together. That rule does not alone ensure that the values used to decide what to write stay appropriate while another transaction changes related data. Visibility of unfinished changes is an isolation question.',[ev(T,'3.4, opening bank-transfer example','A partial transfer is prevented by all-or-nothing grouping.'),ev(P,'13.2.2, business-rule limitation','A transaction snapshot still need not preserve every cross-transaction business rule.')])
put('overlap','Concurrent means transaction lifetimes overlap. A can read, B can read, A can write, and B can write before both finish; no physically simultaneous CPU execution is required. Each SQL statement can correctly act on its permitted inputs while those inputs omit a competing decision.',[ev(P,'13.2.3, concurrent A/B example','Transactions can read before the other transaction writes.'),ev(M,'17.7.2.1, Session A and Session B UPDATE example','Separate sessions issue overlapping operations.')])
put('serial','A serial execution completes all of A before starting B, or all of B before starting A. If each transaction preserves a rule whenever it starts from a valid state, either serial order preserves that rule. This is reasoning about complete operations, not merely the order of final writes.',[ev(P,'13.2 opening definition and 13.2.3','Serial comparison concerns complete transactions.'),ev(T,'3.4, bank-transfer example','Correctness concerns the grouped operation.')])
put('interference','Constructed example: two staff rows, A and B, initially have on_call=true; the rule requires at least one true. Each transaction reads the other row and sets its own row false only if the other is true. Either operation alone preserves the rule. If both read first, both decisions pass, then they update different rows and both can commit under PostgreSQL Repeatable Read. The result has nobody on call. The writes are correct for each transaction’s observations; the combined decision is wrong.',[ev(P,'13.2.2 business-rule limitation; 13.2.3 read/write anomaly example','Stable snapshots can allow a combined result with no serial equivalent; the on-call example is our deduction, not a reported source example.','constructed example using documented semantics')])
put('visibility','A read observes a particular permitted state, not necessarily every latest change. Distinguish another transaction’s uncommitted work, its committed work, and this transaction’s own earlier writes. PostgreSQL ordinary SELECT sees its own preceding updates, even before commit; its view of other transactions depends on isolation level.',[ev(P,'13.2.1, opening SELECT paragraphs','Ordinary SELECT visibility distinguishes other transactions from own writes.'),ev(S,'No Isolation Between Operations On The Same Database Connection','Same-connection writes are visible to later reads.')])
put('anomalies','A dirty read sees someone else’s unfinished update. A nonrepeatable read sees a previously read value change after another commit. A phantom read sees the rows satisfying the same WHERE condition change after another commit. A serialization anomaly means the committed outcome matches no ordering of complete transactions. Stable individual reads therefore do not by themselves rule out every bad combined outcome.',[ev(P,'13.2, four phenomenon definitions and Table 13.1','Defines the four distinctions used to compare guarantees.')])
put('snapshot','A snapshot is the database state a read is allowed to observe. Multiversion concurrency control (MVCC) keeps distinguishable versions so a read can use an earlier state while other work writes newer data. PostgreSQL Read Committed ordinary SELECT uses a new snapshot per statement; Repeatable Read uses the first non-control statement’s snapshot for the transaction, plus its own writes.',[ev(V,'13.1 opening paragraphs','MVCC lets statements observe an earlier database version.','supplemental live source'),ev(P,'13.2.1 and 13.2.2 snapshot timing','Read Committed and Repeatable Read choose snapshots at different boundaries.')])
put('levels','The conventional four-level comparison specifies forbidden outcomes. Read Uncommitted may allow all four anomalies; Read Committed forbids dirty reads; Repeatable Read also forbids nonrepeatable reads but its minimum guarantee can allow phantoms and serialization anomalies; Serializable forbids all four. Products can exceed these minima: PostgreSQL Read Uncommitted behaves as Read Committed, and its Repeatable Read also prevents phantoms. A level is a guarantee about allowed behavior.',[ev(P,'13.2 Table 13.1 and following paragraphs','Level minima differ from PostgreSQL implementations.')])
put('snapshot_limit','In the on-call example both transaction snapshots contain two available staff. Each changes a different row, so a same-row write collision need not occur. A then B would leave B on call because B reads A=false; B then A would leave A on call. Both-off fits neither order. Repeatable reads stabilize observations but do not necessarily protect the assumptions linking reads of one row to writes of another.',[ev(P,'13.2.2 and 13.2.3','PostgreSQL snapshot isolation permits serialization anomalies; constructed schedule applies that rule.','constructed deduction supported by supplied and live source')])
put('serializable','Serializable promises that successfully committed transactions have an effect equivalent to some serial order. Actual work may overlap. If every participating operation preserves the application rule in isolation, this guarantee preserves it across their committed combination. It cannot repair logically incorrect operations or a workflow whose required reads occur outside its transaction.',[ev(P,'13.2.3 opening and consistent-use discussion','Committed work is equivalent to serial execution; correctness depends on correct individual transactions.')])
put('mechanisms','A mechanism is how the database enforces its promise. Snapshots choose visible versions. Blocking locks reserve access so a conflicting operation waits; protecting a searched range can also prevent new matching rows. Conflict checking instead detects combinations of reads and writes incompatible with the promised order and rejects work. PostgreSQL Serializable adds such checks to snapshots; its read-dependency tracking is not a blocking read lock. Engines can combine these techniques.',[ev(M,'17.7.2.1 REPEATABLE READ locking rules','Record and range protection can make competing operations wait.'),ev(P,'13.2.3 monitoring and predicate locks','PostgreSQL uses dependency tracking and serialization failures.'),ev(V,'13.1','MVCC provides a distinct concurrency-control mechanism.','supplemental live source')])
put('engine_details','Do not apply ordinary SELECT rules automatically to UPDATE or locking reads. InnoDB 8.4 Repeatable Read ordinary reads share a snapshot, while locking reads/modifications protect searched records or ranges. With autocommit disabled, its Serializable level treats plain SELECT as shared locking reads. SQLite WAL supports concurrent snapshot readers but only one writer; a stale reader attempting to write can fail with SQLITE_BUSY_SNAPSHOT. Thus using snapshots does not imply that every engine permits the on-call anomaly.',[ev(M,'17.7.2.1 REPEATABLE READ and SERIALIZABLE','Statement type and autocommit alter behavior.'),ev(S,'Isolation Between Database Connections; Isolation And Concurrency','Single-writer enforcement and stale-snapshot rejection complement snapshots.')])
put('retries','A serialization failure means the attempted transaction could not be safely accepted with competing work. Discard it and retry the whole transaction, including its reads and decisions, from fresh state; replaying only its final write can repeat the invalid decision. PostgreSQL Repeatable Read can require this too. SQLite stale-snapshot rejection similarly requires releasing the old snapshot before starting again. A rejection can be how isolation protects correctness.',[ev(P,'13.2.2 concurrent-update failure; 13.2.3 retry requirement','Entire transactions must be retried after serialization failures.'),ev(S,'Isolation And Concurrency, X upgrading to writer','Stale read snapshots must be released before retrying writes.')])
put('choice','Start with the rule and all reads and writes needed to preserve it. Choose guarantees that exclude the dangerous interleavings, using the actual engine and statement behavior. Serializable provides general serial-equivalence protection for correctly bounded transactions, with retry handling. Weaker levels may suffice for narrower operations with appropriate coordination. Waiting, rejected attempts, and performance depend on workload; no universally fastest or best level follows from these sources.',[ev(P,'13.2.1 simple versus complex operations; 13.2.3 consistent Serializable use','Different operations need different protection; retries and checks have costs.'),ev(M,'17.7.2.1 introduction and locking behavior','Isolation choices affect coordination and contention.')])
put('target','Two individually correct operations can base their decisions on observations that omit each other’s changes; their combined writes can then break an application rule. Transaction boundaries make work a unit, while isolation constrains what overlapping units may observe and commit. Weaker guarantees exclude particular read anomalies; even stable snapshots can permit incompatible decisions. Serializable excludes outcomes with no serial equivalent, often by waiting or rejecting work that must be retried. The engine, statements, and correctly chosen transaction boundaries determine how those guarantees apply.',[ev(P,'13.2 Table 13.1, 13.2.2, 13.2.3','Explains observation guarantees, snapshot limits, serial equivalence and retries.'),ev(T,'3.4','Defines operation boundaries and atomicity.'),ev(M,'17.7.2.1','Shows implementation and statement distinctions.'),ev(S,'Isolation And Concurrency','Shows another mechanism for preventing incompatible histories.')])
g['revisions'].append({'round':1,'stage':'primary-source-verification','gaps':['Precise snapshot boundaries','Concrete shared-rule failure','Meaning of MVCC','Retries and statement-specific behavior'],'searches':[{'type':'direct-open','urls':[P,T,M,S],'purpose':'Read packet sources in full relevant sections, pin PostgreSQL to version 18.'},{'type':'direct-open','urls':[V],'purpose':'Close mechanism gap: how an earlier visible database version relates to MVCC.'}],'evidence':[P,T,M,S,V],'changes':['Filled all researched answers and attached locators.','Added constructed on-call example, explicitly distinguished from published example.','Verified snapshot timing, same-connection visibility, engine qualifications and whole-transaction retry.']})
(p/'round-1-dag.json').write_text(json.dumps(g,indent=2)+'\n')
# Review reveals an assumed correctness concept that the reader did not claim.
n=next(n for n in g['nodes'] if n['id']=='sql_state')
n['question']='What SQL knowledge can the explanation assume?'
n['answer']='The reader can read SELECT, UPDATE, WHERE and recognize table rows and column values. No transaction or concurrency-control vocabulary is assumed.'
g['nodes'].insert(1,{'id':'correctness','question':'What makes a database operation correct for an application?','answer':'The application has a rule that should hold in completed states: for example, a transfer preserves the combined account balance. Such a rule is often called an invariant. An operation is correct in isolation when, starting from a state satisfying the rule, its complete execution leaves the rule satisfied. Valid SQL alone does not establish that property.','status':'supported','evidence':[ev(T,'3.4 bank-transfer example','The complete transfer must preserve the intended relationship between account balances.','source-grounded definition and synthesis')]})
# Replace motivation/order edges with the actual knowledge used in final answers.
g['edges']=[e for e in g['edges'] if (e['from'],e['to']) not in {('sql_state','interference'),('levels','serializable'),('snapshot_limit','serializable')}]
for a,b,w in [('sql_state','correctness','A rule refers to the rows and values the reader already recognizes.'),('correctness','serial','The preservation argument needs a definition of individually correct operations.'),('correctness','interference','Calling the combined outcome wrong requires the shared rule.'),('serial','serializable','Serializable is defined by equivalence to a serial order.'),('snapshot_limit','choice','A safe choice must account for failures that stable reads alone do not exclude.'),('serial','mechanisms','Conflict-checking explanations refer to compatibility with a serial order.')]:
 g['edges'].append({'from':a,'to':b,'why':w})
g['reader_assumptions']=g['reader_assumptions'][:2]
g['scope']={'included':['Single-database transactions on separate connections','Atomicity versus isolation','Observation anomalies and snapshot boundaries','Constructed cross-row write-skew example','Serializable effects versus concurrency-control mechanisms','Product-qualified PostgreSQL 18, InnoDB 8.4 and SQLite examples','Whole-transaction retry requirement'],'excluded':['Distributed transactions and replicas','Durability/storage recovery internals','All lock types and query-plan-dependent lock footprints','Production performance recommendations','External-service side effects and retry idempotency design'],'limits':['No live database workload executed; example verified with a state-transition model and documentation.','No SQL standard text directly consulted; standard minimum comparison is attributed to PostgreSQL documentation.','No full report or graph rendering performed: graph-only task with shared renderer.']}
g['constructed_example']={'id':'on-call','kind':'original worked deduction, not a source measurement','assumptions':['Two different rows initially true.','Each transaction reads the other row, then updates only its own row if the other is true.','Both transactions run PostgreSQL Repeatable Read; no extra rule-enforcing constraint or explicit coordination.','Both read before either commits; both writes target different rows.'],'transactions':{'A':['BEGIN ISOLATION LEVEL REPEATABLE READ','SELECT on_call FROM staff WHERE id = \'B\'','If true: UPDATE staff SET on_call = false WHERE id = \'A\'','COMMIT'],'B':['BEGIN ISOLATION LEVEL REPEATABLE READ','SELECT on_call FROM staff WHERE id = \'A\'','If true: UPDATE staff SET on_call = false WHERE id = \'B\'','COMMIT']},'serial_outcomes':[[False,True],[True,False]],'concurrent_outcome':[False,False],'verification':'checks.json records state-model verification; this is not a PostgreSQL integration test.'}
g['revisions'].append({'round':2,'stage':'prerequisite-and-synthesis-review','gaps':['Correctness/invariant was improperly folded into assumed SQL knowledge.','Two edges described motivating order rather than necessary definitions.'],'searches':[],'evidence':[T,P],'changes':['Added explicit correctness node grounded in transfer example.','Narrowed assumed root to actual reader baseline.','Replaced levels→serializable and snapshot_limit→serializable with serial→serializable.','Connected snapshot limitation to guarantee selection and serial order to conflict-checking mechanism.','Reviewed each answer for undefined prerequisites and preserved product-specific limits.']})
(p/'dag.json').write_text(json.dumps(g,indent=2)+'\n')
print('Final graph saved:',len(g['nodes']),'nodes,',len(g['edges']),'edges')
